import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"設定リファレンス","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/index.md","filePath":"ja-JP/user-guide/settings/index.md","lastUpdated":1785993908000}'),s={name:"ja-JP/user-guide/settings/index.md"};function h(n,t,i,l,o,p){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="設定リファレンス" tabindex="-1">設定リファレンス <a class="header-anchor" href="#設定リファレンス" aria-label="Permalink to &quot;設定リファレンス&quot;">​</a></h1><p>設定ウィンドウは通常のウィンドウと同じようにサイズ変更も最大化もできます。端をドラッグするか、タイトルバーの最大化ボタン、またはタイトルバーのダブルクリックで切り替えられます。とくにプラグインページで効果があります。プラグイン一覧とそのプラグインの設定を左右に並べるページなので、幅がそのまま活きます。</p><p>設定ウィンドウのタイトルバーには検索ボックスがあります。これは単純な部分一致だけでなく、あいまい検索(メイン検索ウィンドウと同じ fzf 方式のマッチングで、ピンインエイリアスにも対応)ですべてのセクション(プラグイン配下のプラグインごとのエントリ、ホットキーのプラグインアクションタブを含む)を横断して検索します。各結果にはパンくずリスト(例:「インデックス &gt; ネットワークドライブ」)が表示されるため、異なるタブに同名の設定があっても区別できます。結果を選択する(クリック、または上下キーでハイライトして Enter)と、該当するセクションとタブに切り替わり、対象のコントロールまでスクロールして表示し、その周囲に一瞬ハイライト枠が点滅します。</p><p>いくつかのセクション(一般、ホットキー、インデックス、履歴、クイックパネル、サービスの状態)は、ページ上部に独自のサブタブの行にさらに分かれています。タブのラベルがすべて収まらない場合(翻訳後のラベルは中国語の原文より長くなることが多いため、英語で最も起こりやすい)、行の両端に左右の矢印ボタンが表示され、単に切り捨てられるのではなく、スクロールして残りにアクセスできるようになります。</p><p>設定ウィンドウの左サイドバーには10個のセクションがあります:</p><table tabindex="0"><thead><tr><th>セクション</th><th>内容</th></tr></thead><tbody><tr><td><a href="./service-status.html">サービスの状態</a></td><td>バックグラウンドサービスのインストール、および App/Hook/Service ログビューアー。</td></tr><tr><td><a href="./index-drives.html">インデックス</a></td><td>ローカルドライブ、ネットワークドライブ、WSL ディストリビューション(検出時)、フォルダーインデックス、除外ルール。</td></tr><tr><td><a href="./general.html">一般</a></td><td>起動時の動作、アップデート、言語、検索バーのレイアウト、プレビューウィンドウのサイズ。</td></tr><tr><td><a href="./hotkeys-page.html">ホットキー</a></td><td>グローバルホットキー、プラグインごとのアクションホットキー、プロセスブラックリスト。</td></tr><tr><td><a href="./plugins.html">プラグイン</a></td><td>インストール済みプラグインとコンポーネントごとの有効/無効切り替え。</td></tr><tr><td><a href="./localsend.html">LocalSend</a></td><td>ローカルネットワーク経由でのファイル、フォルダ、プレーンテキスト転送設定。</td></tr><tr><td><a href="./favorites.html">お気に入り</a></td><td>フォルダー、ファイル、URL へのカスタム名付きショートカット。</td></tr><tr><td><a href="./history.html">履歴</a></td><td>検索履歴とクイックウィンドウのキーワード履歴。</td></tr></tbody></table><p>| <a href="./quick-panel.html">クイックパネル</a> | 前面のウィンドウに重ねてドッキングするフローティングパネル:そのワークスペース、各ワークスペースのソース、プラグインが提供するタブ、そして各ワークスペースがどのアプリに属するか。 | | <a href="./appearance.html">外観</a> | テーマ選択(テーマごとのプレビューカード付き)と「システムのライト/ダークに従う」モード。バージョン情報の上に固定表示。 | | <a href="./about.html">バージョン情報</a> | バージョン情報とアップデート確認。 |</p><p>以下の各ページでは、そのセクションのすべてのオプションを順に、デフォルト値と有効な範囲とともに説明しています。</p>',8)])])}const m=e(s,[["render",h]]);export{c as __pageData,m as default};
